fn findMax(a: &[i32], n: usize) -> usize {
    // Precondition: 0 < n <= a.len()
    debug_assert!(n > 0 && n <= a.len());

    // Start by assuming the first element of the prefix is the maximum.
    let mut max_idx = 0;

    // Iterate over the rest of the prefix and update max_idx whenever
    // we find a strictly larger value.
    for i in 1..n {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
    }

    max_idx
}

